package main

import "fmt"

type Principal struct{ Subject, Tenant, Role string }
type Document struct{ Tenant, Owner string }

func canRead(p Principal, d Document) bool {
	return p.Subject != "" && p.Tenant == d.Tenant && (p.Subject == d.Owner || p.Role == "auditor")
}
func main() {
	// These are already-verified test principals, not values read from headers.
	d := Document{Tenant: "a", Owner: "user-1"}
	fmt.Println(canRead(Principal{"user-1", "a", "reader"}, d)) // true
	fmt.Println(canRead(Principal{"user-1", "b", "reader"}, d)) // false
}

package main

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"fmt"
)

func tag(key, message []byte) []byte {
	m := hmac.New(sha256.New, key)
	_, _ = m.Write(message)
	return m.Sum(nil)
}
func main() {
	key := make([]byte, 32)
	if _, err := rand.Read(key); err != nil {
		panic(err)
	}
	message := []byte("action=read;resource=7")
	expected := tag(key, message)
	fmt.Println(hmac.Equal(expected, tag(key, message)))                           // true
	fmt.Println(hmac.Equal(expected, tag(key, []byte("action=write;resource=7")))) // false
	// Never print key material; a MAC does not hide the message.
}

