package main

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"io"
	"strings"
)

// recordingDriver is a test double: it prints what database/sql hands to a
// driver and returns no rows. A real driver sends the same two parts to the
// database server.
type recordingDriver struct{}

func (recordingDriver) Open(string) (driver.Conn, error) { return conn{}, nil }

type conn struct{}

func (conn) Prepare(string) (driver.Stmt, error) { return nil, errors.New("prepare not supported") }
func (conn) Close() error                        { return nil }
func (conn) Begin() (driver.Tx, error)           { return nil, errors.New("transactions not supported") }

// QueryContext receives the SQL text and the arguments as separate values.
func (conn) QueryContext(_ context.Context, query string, args []driver.NamedValue) (driver.Rows, error) {
	vals := make([]string, len(args))
	for i, a := range args {
		vals[i] = fmt.Sprintf("$%d=%T(%#v)", a.Ordinal, a.Value, a.Value)
	}
	fmt.Printf("  sql:  %s\n  args: [%s]\n", query, strings.Join(vals, " "))
	return emptyRows{}, nil
}

type emptyRows struct{}

func (emptyRows) Columns() []string         { return []string{"id"} }
func (emptyRows) Close() error              { return nil }
func (emptyRows) Next([]driver.Value) error { return io.EOF }

// sortColumns maps a public sort key to a fixed SQL fragment.
var sortColumns = map[string]string{
	"name":   "name ASC",
	"newest": "created_at DESC",
}

// likeEscaper makes %, _ and the escape character itself literal.
var likeEscaper = strings.NewReplacer("!", "!!", "%", "!%", "_", "!_")

func run(ctx context.Context, db *sql.DB, query string, args ...any) {
	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		fmt.Println("  error:", err)
		return
	}
	defer rows.Close()
	for rows.Next() {
	}
	if err := rows.Err(); err != nil {
		fmt.Println("  error:", err)
	}
}

func main() {
	sql.Register("recorder", recordingDriver{})
	db, err := sql.Open("recorder", "")
	if err != nil {
		panic(err)
	}
	defer db.Close()
	ctx := context.Background()
	name := "x' OR '1'='1"

	fmt.Println("concatenated (vulnerable):")
	run(ctx, db, "SELECT id FROM users WHERE name = '"+name+"'")

	fmt.Println("parameterized:")
	run(ctx, db, "SELECT id FROM users WHERE name = $1", name)

	fmt.Println("allow-listed ORDER BY:")
	for _, key := range []string{"newest", "name; DROP TABLE users"} {
		order, ok := sortColumns[key]
		if !ok {
			fmt.Printf("  rejected sort key %q\n", key)
			continue
		}
		run(ctx, db, "SELECT id FROM users ORDER BY "+order+" LIMIT $1", 20)
	}

	fmt.Println("LIKE with escaped wildcards:")
	pattern := "%" + likeEscaper.Replace("50%_off!") + "%"
	run(ctx, db, "SELECT id FROM products WHERE title LIKE $1 ESCAPE '!'", pattern)
}

// placeholders(3) == "$1, $2, $3"; the values themselves stay in args.
func placeholders(n int) string {
	parts := make([]string, n)
	for i := range parts {
		parts[i] = "$" + strconv.Itoa(i+1)
	}
	return strings.Join(parts, ", ")
}

func postsByID(ctx context.Context, db *sql.DB, ids []int64) (*sql.Rows, error) {
	if len(ids) == 0 || len(ids) > 500 {
		return nil, errors.New("between 1 and 500 ids")
	}
	query := "SELECT id, title FROM posts WHERE id IN (" + placeholders(len(ids)) + ")"
	args := make([]any, len(ids))
	for i, id := range ids {
		args[i] = id
	}
	return db.QueryContext(ctx, query, args...)
}

