import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
)

func newHandler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /transfer", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "transfer accepted")
	})
	mux.HandleFunc("GET /balance", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "balance shown")
	})
	mux.HandleFunc("POST /sso/acs", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "assertion checked")
	})

	cop := http.NewCrossOriginProtection()
	if err := cop.AddTrustedOrigin("https://checkout.partner.example"); err != nil {
		panic(err)
	}
	// The identity provider posts a signed form cross-site by design.
	cop.AddInsecureBypassPattern("POST /sso/acs")
	cop.SetDenyHandler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "cross-origin request rejected", http.StatusForbidden)
	}))
	return cop.Handler(mux)
}

type probe struct {
	label, method, path, fetchSite, origin string
}

func main() {
	h := newHandler()
	probes := []probe{
		{"same-origin form", "POST", "/transfer", "same-origin", "https://example.com"},
		{"cross-site form", "POST", "/transfer", "cross-site", "https://attacker.example"},
		{"sibling subdomain", "POST", "/transfer", "same-site", "https://blog.example.com"},
		{"cross-site GET", "GET", "/balance", "cross-site", ""},
		{"old browser, Origin only", "POST", "/transfer", "", "https://attacker.example"},
		{"old browser, same host", "POST", "/transfer", "", "https://example.com"},
		{"curl, no headers", "POST", "/transfer", "", ""},
		{"trusted partner", "POST", "/transfer", "cross-site", "https://checkout.partner.example"},
		{"SSO bypass pattern", "POST", "/sso/acs", "cross-site", "https://idp.example"},
	}
	for _, p := range probes {
		req := httptest.NewRequest(p.method, p.path, nil) // Host is example.com
		if p.fetchSite != "" {
			req.Header.Set("Sec-Fetch-Site", p.fetchSite)
		}
		if p.origin != "" {
			req.Header.Set("Origin", p.origin)
		}
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
		fmt.Printf("%-26s %d %s\n", p.label, rec.Code, strings.TrimSpace(rec.Body.String()))
	}
}

