package main

import (
	"crypto/rand"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"time"
)

const cookieName = "__Host-session"

var (
	errNoSession   = errors.New("session not found")
	errIdleExpired = errors.New("session expired (idle)")
	errAbsExpired  = errors.New("session expired (absolute)")
)

type session struct {
	userID   string
	created  time.Time
	lastSeen time.Time
}

// store owns every session; the cookie only carries an unguessable key.
type store struct {
	mu       sync.Mutex
	byID     map[string]*session
	now      func() time.Time
	idle     time.Duration
	absolute time.Duration
}

func (s *store) create(userID string) string {
	s.mu.Lock()
	defer s.mu.Unlock()
	id := rand.Text() // at least 128 bits from crypto/rand
	t := s.now()
	s.byID[id] = &session{userID: userID, created: t, lastSeen: t}
	return id
}

func (s *store) lookup(id string) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sess, ok := s.byID[id]
	if !ok {
		return "", errNoSession
	}
	t := s.now()
	switch {
	case t.Sub(sess.created) > s.absolute:
		delete(s.byID, id)
		return "", errAbsExpired
	case t.Sub(sess.lastSeen) > s.idle:
		delete(s.byID, id)
		return "", errIdleExpired
	}
	sess.lastSeen = t
	return sess.userID, nil
}

// login discards the pre-login session and issues a fresh ID.
func (s *store) login(oldID, userID string) string {
	s.destroy(oldID)
	return s.create(userID)
}

func (s *store) destroy(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.byID, id)
}

func sessionCookie(id string, maxAge int) *http.Cookie {
	return &http.Cookie{
		Name:     cookieName,
		Value:    id,
		Path:     "/",
		MaxAge:   maxAge,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
	}
}

func setCookieHeader(c *http.Cookie) string {
	rec := httptest.NewRecorder()
	http.SetCookie(rec, c)
	h := rec.Header().Get("Set-Cookie")
	if c.Value != "" {
		h = strings.Replace(h, c.Value, "<id>", 1)
	}
	return h
}

func show(label string, st *store, id string) {
	user, err := st.lookup(id)
	if err != nil {
		fmt.Printf("%s: %v\n", label, err)
		return
	}
	fmt.Printf("%s: ok %s\n", label, user)
}

func main() {
	clock := time.Date(2026, 1, 5, 9, 0, 0, 0, time.UTC)
	st := &store{
		byID:     map[string]*session{},
		now:      func() time.Time { return clock },
		idle:     30 * time.Minute,
		absolute: 8 * time.Hour,
	}

	// An attacker can plant a pre-login ID in the victim's browser.
	planted := st.create("")
	id := st.login(planted, "user-42")
	fmt.Println(setCookieHeader(sessionCookie(id, int(st.absolute.Seconds()))))
	show("planted pre-login ID", st, planted)
	fmt.Printf("new ID differs: %t, length %d\n", id != planted, len(id))

	clock = clock.Add(20 * time.Minute)
	show("after 20m", st, id)
	clock = clock.Add(31 * time.Minute)
	show("after 31m without a request", st, id)

	id = st.login("", "user-42")
	for range 19 { // a request every 25 minutes keeps the idle timer fresh
		clock = clock.Add(25 * time.Minute)
		if _, err := st.lookup(id); err != nil {
			fmt.Println("unexpected:", err)
		}
	}
	show("busy session at 7h55m", st, id)
	clock = clock.Add(25 * time.Minute)
	show("busy session at 8h20m", st, id)

	id = st.login("", "user-42")
	st.destroy(id) // logout invalidates the record on the server
	show("replayed cookie after logout", st, id)
	fmt.Println(setCookieHeader(sessionCookie("", -1)))
}

