package main

import (
	"fmt"
	"os"
	"path/filepath"
)

// naiveRead looks careful but only manipulates strings.
func naiveRead(base, name string) string {
	data, err := os.ReadFile(filepath.Join(base, filepath.Clean(name)))
	if err != nil {
		return "error"
	}
	return string(data)
}

// rootRead resolves every component inside the opened directory.
func rootRead(root *os.Root, name string) string {
	data, err := root.ReadFile(name)
	if err != nil {
		return "denied: " + err.Error()
	}
	return string(data)
}

func main() {
	dir, err := os.MkdirTemp("", "traversal-demo-*")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)

	public := filepath.Join(dir, "public")
	must(os.Mkdir(public, 0o755))
	must(os.WriteFile(filepath.Join(public, "readme.txt"), []byte("public notes"), 0o644))
	must(os.WriteFile(filepath.Join(dir, "secret.txt"), []byte("SECRET"), 0o600))
	// A relative symlink that a user upload or a bad deploy could leave behind.
	must(os.Symlink("../secret.txt", filepath.Join(public, "latest.txt")))

	root, err := os.OpenRoot(public)
	if err != nil {
		panic(err)
	}
	defer root.Close()

	for _, name := range []string{"readme.txt", "../secret.txt", "/readme.txt", "latest.txt"} {
		fmt.Printf("%-15q IsLocal=%-5t join=%-12s root=%s\n",
			name, filepath.IsLocal(name), naiveRead(public, name), rootRead(root, name))
	}
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

package main

import (
	"archive/zip"
	"bytes"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
)

const maxFileBytes = 1 << 20

// extract writes regular files from zr beneath root and refuses everything else.
func extract(root *os.Root, zr *zip.Reader) error {
	for _, f := range zr.File {
		if f.FileInfo().IsDir() {
			continue // directories are created on demand below
		}
		// Zip names are slash-separated; Localize rejects absolute names,
		// ".." elements and names the OS cannot represent.
		name, err := filepath.Localize(f.Name)
		if err != nil {
			fmt.Printf("skip %q: not a local path\n", f.Name)
			continue
		}
		if !f.Mode().IsRegular() {
			fmt.Printf("skip %q: not a regular file\n", f.Name)
			continue
		}
		if err := root.MkdirAll(filepath.Dir(name), 0o755); err != nil {
			return err
		}
		if err := copyFile(root, name, f); err != nil {
			return fmt.Errorf("%s: %w", f.Name, err)
		}
		fmt.Printf("wrote %q\n", name)
	}
	return nil
}

func copyFile(root *os.Root, name string, f *zip.File) error {
	src, err := f.Open()
	if err != nil {
		return err
	}
	defer src.Close()
	dst, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return err
	}
	n, err := io.Copy(dst, io.LimitReader(src, maxFileBytes+1))
	if cerr := dst.Close(); err == nil {
		err = cerr
	}
	if err == nil && n > maxFileBytes {
		err = errors.New("file exceeds size limit")
	}
	return err
}

func hostileArchive() *bytes.Reader {
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	add := func(name string, mode fs.FileMode, body string) {
		h := &zip.FileHeader{Name: name, Method: zip.Deflate}
		h.SetMode(mode)
		w, err := zw.CreateHeader(h)
		if err != nil {
			panic(err)
		}
		if _, err := io.WriteString(w, body); err != nil {
			panic(err)
		}
	}
	add("readme.txt", 0o644, "hello")
	add("docs/guide.txt", 0o644, "guide")
	add("../../escape.txt", 0o644, "zip slip")
	add("/etc/cron.d/job", 0o644, "absolute")
	add("docs/link", fs.ModeSymlink|0o777, "../../../home")
	if err := zw.Close(); err != nil {
		panic(err)
	}
	return bytes.NewReader(buf.Bytes())
}

func main() {
	dir, err := os.MkdirTemp("", "unzip-demo-*")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	root, err := os.OpenRoot(dir)
	if err != nil {
		panic(err)
	}
	defer root.Close()

	ra := hostileArchive()
	zr, err := zip.NewReader(ra, ra.Size())
	if err != nil && !errors.Is(err, zip.ErrInsecurePath) {
		panic(err)
	}
	if err := extract(root, zr); err != nil {
		fmt.Println("extract failed:", err)
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
	"syscall"
	"time"
)

// Vulnerable: the shell parses name as syntax, so ; | $( ) all work.
func countViaShell(name string) *exec.Cmd {
	return exec.Command("sh", "-c", "wc -l "+name)
}

// countLines passes name as one argv element and ends option parsing first.
func countLines(ctx context.Context, name string) (*exec.Cmd, error) {
	if name == "" || strings.HasPrefix(name, "-") {
		return nil, errors.New("file name must not be empty or start with '-'")
	}
	return exec.CommandContext(ctx, "wc", "-l", "--", name), nil
}

// gitOps is the whole surface a request can reach: fixed argv per operation.
var gitOps = map[string][]string{
	"status": {"status", "--porcelain=v1"},
	"log":    {"log", "--oneline", "--max-count=20"},
}

func gitCommand(ctx context.Context, op string) (*exec.Cmd, error) {
	args, ok := gitOps[op]
	if !ok {
		return nil, fmt.Errorf("operation %q is not allowed", op)
	}
	cmd := exec.CommandContext(ctx, "git", args...)
	cmd.Dir = "/srv/repos/site"
	cmd.Env = []string{"PATH=/usr/bin:/bin", "LANG=C", "GIT_TERMINAL_PROMPT=0"}
	cmd.Cancel = func() error { return cmd.Process.Signal(syscall.SIGTERM) }
	cmd.WaitDelay = 2 * time.Second
	return cmd, nil
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	hostile := "report.txt; touch pwned"
	fmt.Printf("shell argv: %q\n", countViaShell(hostile).Args)

	for _, name := range []string{hostile, "--files0-from=/etc/passwd", "-"} {
		cmd, err := countLines(ctx, name)
		if err != nil {
			fmt.Printf("rejected %q: %v\n", name, err)
			continue
		}
		fmt.Printf("direct argv: %q\n", cmd.Args)
	}

	for _, op := range []string{"log", "push"} {
		cmd, err := gitCommand(ctx, op)
		if err != nil {
			fmt.Println("rejected:", err)
			continue
		}
		fmt.Printf("git argv: %q\n", cmd.Args)
		fmt.Printf("git env:  %q\n", cmd.Env)
		fmt.Println("git wait delay:", cmd.WaitDelay)
	}
	// Nothing above calls Run, Start or Output: no process was started.
}

ctx, cancel := context.WithTimeout(r.Context(), 10*time.Second)
defer cancel()
cmd, err := gitCommand(ctx, r.PathValue("op"))
if err != nil {
	http.Error(w, "unknown operation", http.StatusBadRequest)
	return
}
out := newLimitedBuffer(1 << 20) // an io.Writer that fails past 1 MiB
cmd.Stdout, cmd.Stderr = out, out
if err := cmd.Run(); err != nil {
	if ctx.Err() != nil {
		http.Error(w, "operation timed out", http.StatusGatewayTimeout)
		return
	}
	log.Printf("git %q failed: %v", cmd.Args, err)
	http.Error(w, "operation failed", http.StatusInternalServerError)
	return
}

package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
)

// allowedHosts lists the only absolute destinations; compare exact hostnames.
var allowedHosts = map[string]bool{"docs.example.com": true}

func redirectTarget(raw string) (string, error) {
	if raw == "" {
		return "", errors.New("empty")
	}
	// Browsers treat \ like / and strip tabs and newlines; Go's parser does not.
	if strings.ContainsFunc(raw, func(r rune) bool { return r == '\\' || r < 0x20 || r == 0x7f }) {
		return "", errors.New("backslash or control character")
	}
	u, err := url.Parse(raw)
	if err != nil {
		return "", errors.New("unparseable")
	}
	if u.Scheme == "" && u.Host == "" && u.User == nil {
		if !strings.HasPrefix(raw, "/") || strings.HasPrefix(raw, "//") {
			return "", errors.New("relative target must start with exactly one /")
		}
		return u.String(), nil
	}
	// u.Host includes any port, so "docs.example.com:8443" is not allowed either.
	if !allowedHosts[u.Host] {
		return "", fmt.Errorf("host %q not allowed", u.Host)
	}
	if u.Scheme != "https" || u.User != nil {
		return "", errors.New("only https URLs without userinfo")
	}
	return u.String(), nil
}

// naiveTarget is a common first attempt: a local path or "our" docs prefix.
func naiveTarget(raw string) bool {
	return strings.HasPrefix(raw, "/") || strings.HasPrefix(raw, "https://docs.example.com")
}

func main() {
	inputs := []string{
		"/settings?tab=keys",
		"https://docs.example.com/guide",
		"http://docs.example.com/guide",
		"//evil.example/login",
		`/\evil.example`,
		"/\t/evil.example",
		"https://docs.example.com@evil.example/",
		"https://docs.example.com.evil.example/",
		"https:evil.example",
		"javascript:alert(1)",
		"settings",
	}
	for _, in := range inputs {
		naive := "reject"
		if naiveTarget(in) {
			naive = "allow"
		}
		if target, err := redirectTarget(in); err != nil {
			fmt.Printf("%-42q naive=%-6s safe=reject (%v)\n", in, naive, err)
		} else {
			fmt.Printf("%-42q naive=%-6s safe=allow %s\n", in, naive, target)
		}
	}

	// The handler falls back to a fixed page instead of echoing bad input.
	h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		target, err := redirectTarget(r.URL.Query().Get("next"))
		if err != nil {
			target = "/"
		}
		http.Redirect(w, r, target, http.StatusSeeOther)
	})
	for _, next := range []string{"/settings", "//evil.example"} {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest("POST", "/login?next="+url.QueryEscape(next), nil))
		fmt.Printf("POST /login next=%s -> %d Location: %s\n", next, rec.Code, rec.Header().Get("Location"))
	}
}

package main

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"html/template"
	"net/http"
	"net/http/httptest"
	"strings"
)

type nonceKey struct{}

func newNonce() string {
	b := make([]byte, 16)
	rand.Read(b) // never returns an error; crashes the program if the OS source fails
	return base64.RawURLEncoding.EncodeToString(b)
}

// securityHeaders sets the policy before the inner handler writes anything.
func securityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		nonce := newNonce()
		h := w.Header()
		h.Set("Content-Security-Policy", "default-src 'self'; script-src 'nonce-"+nonce+"'; "+
			"object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
		h.Set("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
		h.Set("X-Content-Type-Options", "nosniff")
		h.Set("X-Frame-Options", "DENY")
		h.Set("Referrer-Policy", "strict-origin-when-cross-origin")
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), nonceKey{}, nonce)))
	})
}

var page = template.Must(template.New("page").Parse(
	`<script nonce="{{.Nonce}}">start()</script><p>{{.Comment}}</p>`))

func handler(w http.ResponseWriter, r *http.Request) {
	nonce, _ := r.Context().Value(nonceKey{}).(string)
	var buf bytes.Buffer
	err := page.Execute(&buf, map[string]any{
		"Nonce": nonce,
		// A bug elsewhere marked stored user input as trusted HTML.
		"Comment": template.HTML(`<script>steal()</script>`),
	})
	if err != nil {
		http.Error(w, "render failed", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	buf.WriteTo(w)
}

func nonceFrom(csp string) string {
	_, rest, _ := strings.Cut(csp, "'nonce-")
	nonce, _, _ := strings.Cut(rest, "'")
	return nonce
}

func main() {
	h := securityHeaders(http.HandlerFunc(handler))
	var nonces []string
	for range 2 {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest("GET", "https://example.com/", nil))
		nonce := nonceFrom(rec.Header().Get("Content-Security-Policy"))
		if len(nonces) == 0 {
			for _, name := range []string{"Content-Security-Policy", "Strict-Transport-Security",
				"X-Content-Type-Options", "X-Frame-Options", "Referrer-Policy"} {
				fmt.Printf("%s: %s\n", name, strings.Replace(rec.Header().Get(name), nonce, "<nonce>", 1))
			}
			fmt.Println("body:", strings.Replace(rec.Body.String(), nonce, "<nonce>", 1))
		}
		nonces = append(nonces, nonce)
	}
	fmt.Println("nonce length:", len(nonces[0]))
	fmt.Println("fresh nonce per response:", nonces[0] != nonces[1])
}

func SecurityHeaders() gin.HandlerFunc {
	return func(c *gin.Context) {
		nonce := newNonce()
		c.Set("cspNonce", nonce)
		c.Header("Content-Security-Policy", "default-src 'self'; script-src 'nonce-"+nonce+"'; "+
			"object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
		c.Header("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
		c.Header("X-Content-Type-Options", "nosniff")
		c.Header("X-Frame-Options", "DENY")
		c.Header("Referrer-Policy", "strict-origin-when-cross-origin")
		c.Next()
	}
}

