const redacted = "[REDACTED]"

// Secret holds a credential. Every formatting path prints a placeholder;
// only Reveal returns the value, so each real use is visible in review.
type Secret struct{ value string }

func NewSecret(v string) Secret { return Secret{value: v} }

func (s Secret) Reveal() string { return s.value }

func (Secret) String() string                { return redacted }
func (Secret) Format(f fmt.State, verb rune) { io.WriteString(f, redacted) }
