func (Secret) MarshalJSON() ([]byte, error)  { return json.Marshal(redacted) }

type Config struct {
	Addr       string
	DBPassword Secret
}

func main() {
	const canary = "canary-7f3a" // a fake value we can search for

	type plain struct{ Addr, DBPassword string }
	fmt.Println("plain field leaks:", strings.Contains(fmt.Sprintf("%+v", plain{":8080", canary}), canary))

	cfg := Config{Addr: ":8080", DBPassword: NewSecret(canary)}
	fmt.Printf("%+v\n", cfg)
	fmt.Printf("%#v %x %q\n", cfg.DBPassword, cfg.DBPassword, cfg.DBPassword)

	type hidden struct{ token Secret }
	fmt.Println("unexported field leaks:", strings.Contains(fmt.Sprintf("%+v", hidden{NewSecret(canary)}), canary))

	var buf bytes.Buffer
	opts := &slog.HandlerOptions{ReplaceAttr: func(groups []string, a slog.Attr) slog.Attr {
		if a.Key == slog.TimeKey && len(groups) == 0 {
			return slog.Attr{} // drop the timestamp so the output is stable
		}
		return a
	}}
	for _, h := range []slog.Handler{slog.NewJSONHandler(&buf, opts), slog.NewTextHandler(&buf, opts)} {
		slog.New(h).Info("config loaded", "db_password", cfg.DBPassword, "config", cfg)
