import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

type Secret struct{ value string }

func (s Secret) Reveal() string              { return s.value }
func (Secret) Format(f fmt.State, verb rune) { io.WriteString(f, "[REDACTED]") }

// loadSecret reads NAME_FILE (a mounted secret file) or NAME, never both.
// Errors name the variable or the path, never the value.
func loadSecret(name string) (Secret, error) {
	path, fromFile := os.LookupEnv(name + "_FILE")
	value, fromEnv := os.LookupEnv(name)
	switch {
	case fromFile && fromEnv:
		return Secret{}, fmt.Errorf("%s: set %s or %s_FILE, not both", name, name, name)
	case fromFile:
		b, err := os.ReadFile(path)
		if err != nil {
			return Secret{}, fmt.Errorf("%s_FILE: %w", name, err)
		}
		value = strings.TrimRight(string(b), "\r\n")
	case !fromEnv:
		return Secret{}, fmt.Errorf("%s: not set; provide %s or %s_FILE", name, name, name)
	}
	if value == "" {
		return Secret{}, fmt.Errorf("%s: empty value", name)
	}
	return Secret{value: value}, nil
}

func main() {
	dir, err := os.MkdirTemp("", "secret-load")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "db_password")
	if err := os.WriteFile(path, []byte("canary-7f3a\n"), 0o600); err != nil {
		panic(err)
	}

	os.Unsetenv("ORDERS_DB_PASSWORD")
	os.Setenv("ORDERS_DB_PASSWORD_FILE", path)
	db, err := loadSecret("ORDERS_DB_PASSWORD")
	fmt.Println(db, err, db.Reveal() == "canary-7f3a")

	os.Setenv("ORDERS_DB_PASSWORD", "also-set")
	_, err = loadSecret("ORDERS_DB_PASSWORD")
	fmt.Println(err)

	os.Unsetenv("ORDERS_API_TOKEN")
	os.Unsetenv("ORDERS_API_TOKEN_FILE")
	_, err = loadSecret("ORDERS_API_TOKEN")
	fmt.Println(err)

	os.Setenv("ORDERS_API_TOKEN", "")
	_, err = loadSecret("ORDERS_API_TOKEN")
	fmt.Println(err)
}

func TestStartupLogDoesNotLeak(t *testing.T) {
	const canary = "canary-7f3a"
	var buf bytes.Buffer
	logger := slog.New(slog.NewJSONHandler(&buf, nil))
	cfg := Config{Addr: ":8080", DBPassword: NewSecret(canary)}

	logStartup(logger, cfg) // the function production calls at boot

	if strings.Contains(buf.String(), canary) {
		t.Fatalf("secret leaked into the startup log: %s", buf.String())
	}
}

package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"crypto/subtle"
	"fmt"
)

// naiveEqual mirrors a hand-written loop (and what == may do): it stops at
// the first mismatch. steps counts the bytes examined, a stand-in for time.
func naiveEqual(a, b []byte) (equal bool, steps int) {
	if len(a) != len(b) {
		return false, 0
	}
	for i := range a {
		steps++
		if a[i] != b[i] {
			return false, steps
		}
	}
	return true, steps
}

// tokenMatches hashes both sides first, so the comparison always runs over
// two 32-byte digests no matter how long the presented token is.
func tokenMatches(presented string, storedDigest [32]byte) bool {
	d := sha256.Sum256([]byte(presented))
	return subtle.ConstantTimeCompare(d[:], storedDigest[:]) == 1
}

func main() {
	secret := []byte("tok_4f9c2a7e81b3d605") // a test token, 20 bytes
	guesses := []string{
		"xxxxxxxxxxxxxxxxxxxx", // nothing right
		"tok_xxxxxxxxxxxxxxxx", // public prefix right
		"tok_4f9c2axxxxxxxxxx", // ten bytes right
		"tok_4f9c2a7e81b3d605", // all right
	}
	for _, g := range guesses {
		eq, steps := naiveEqual(secret, []byte(g))
		fmt.Printf("naive  %s equal=%-5t bytes examined=%d\n", g, eq, steps)
	}

	// Equal-length inputs: work depends only on the length.
	fmt.Println("subtle full match:", subtle.ConstantTimeCompare(secret, []byte(guesses[3])))
	fmt.Println("subtle ten bytes right:", subtle.ConstantTimeCompare(secret, []byte(guesses[2])))
	// Different lengths return 0 immediately: the length itself can leak.
	fmt.Println("subtle short guess:", subtle.ConstantTimeCompare(secret, []byte("tok_")))

	stored := sha256.Sum256(secret)
	fmt.Println("digest match:", tokenMatches("tok_4f9c2a7e81b3d605", stored))
	fmt.Println("digest short guess:", tokenMatches("tok_", stored))

	key := []byte("test-only-hmac-key-0123456789abc")
	mac := func(msg string) []byte {
		m := hmac.New(sha256.New, key)
		m.Write([]byte(msg))
		return m.Sum(nil)
	}
	received := mac("order=42;amount=1999")
	fmt.Println("hmac.Equal valid:", hmac.Equal(mac("order=42;amount=1999"), received))
	fmt.Println("hmac.Equal altered:", hmac.Equal(mac("order=42;amount=1"), received))
	fmt.Println("hmac.Equal truncated:", hmac.Equal(mac("order=42;amount=1999"), received[:16]))
}

func (s *KeyStore) Authenticate(keyID, presented string) (Principal, error) {
	got := sha256.Sum256([]byte(presented))
	rec, found := s.byID[keyID] // keyID is public, e.g. the prefix of the API key
	want := s.dummy             // a random digest, so unknown IDs do the same work
	if found {
		want = rec.Digest
	}
	if subtle.ConstantTimeCompare(got[:], want[:]) != 1 || !found {
		return Principal{}, errUnauthorized // one error for every failure
	}
	return rec.Principal, nil
}

package main

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"fmt"
)

const version = 1

// Keyring maps a key ID to an AEAD. Sealed records carry the ID that
// encrypted them, so old records stay readable after rotation.
type Keyring struct {
	current uint32
	aeads   map[uint32]cipher.AEAD
}

func (k *Keyring) Add(id uint32, key []byte) error {
	block, err := aes.NewCipher(key) // 32-byte key: AES-256
	if err != nil {
		return err
	}
	aead, err := cipher.NewGCMWithRandomNonce(block) // nonce generated and prepended for us
	if err != nil {
		return err
	}
	k.aeads[id], k.current = aead, id
	return nil
}

// header is version(1) || keyID(4). It is authenticated together with the
// record ID, so neither can be changed without failing Open.
func additionalData(header []byte, recordID string) []byte {
	return append(bytes.Clone(header), recordID...)
}

func (k *Keyring) Seal(recordID string, plaintext []byte) []byte {
	header := binary.BigEndian.AppendUint32([]byte{version}, k.current)
	return k.aeads[k.current].Seal(header, nil, plaintext, additionalData(header, recordID))
}

func (k *Keyring) Open(recordID string, blob []byte) ([]byte, error) {
	if len(blob) < 5 || blob[0] != version {
		return nil, errors.New("unsupported record format")
	}
	id := binary.BigEndian.Uint32(blob[1:5])
	aead, ok := k.aeads[id]
	if !ok {
		return nil, fmt.Errorf("unknown key ID %d", id)
	}
	return aead.Open(nil, nil, blob[5:], additionalData(blob[:5], recordID))
}

func newKey() []byte {
	key := make([]byte, 32)
	rand.Read(key) // never fails; crashes the program if the OS source does
	return key
}

func must[T any](v T, err error) T {
	if err != nil {
		panic(err)
	}
	return v
}

func main() {
	ring := &Keyring{aeads: map[uint32]cipher.AEAD{}}
	if err := ring.Add(1, newKey()); err != nil {
		panic(err)
	}
	pii := []byte(`{"iban":"DE89370400440532013000"}`)
	blob := ring.Seal("customer-17", pii)
	fmt.Printf("plaintext %d bytes, sealed %d bytes\n", len(pii), len(blob))
	fmt.Println("two seals differ:", !bytes.Equal(blob, ring.Seal("customer-17", pii)))

	got, err := ring.Open("customer-17", blob)
	fmt.Println("open own row:", string(got), err)
	_, err = ring.Open("customer-99", blob)
	fmt.Println("open copied to another row:", err)

	tampered := bytes.Clone(blob)
	tampered[len(tampered)-20] ^= 0x01
	_, err = ring.Open("customer-17", tampered)
	fmt.Println("open after one flipped bit:", err)

	if err := ring.Add(2, newKey()); err != nil { // rotate: new writes use key 2
		panic(err)
	}
	fresh := ring.Seal("customer-18", pii)
	_, err = ring.Open("customer-17", blob)
	fmt.Println("new record key ID:", binary.BigEndian.Uint32(fresh[1:5]), "old record still opens:", err == nil)
	delete(ring.aeads, 1) // retiring a key before re-encrypting its rows
	_, err = ring.Open("customer-17", blob)
	fmt.Println("after retiring key 1:", err)

	// TEST PATH ONLY: a fixed nonce, to show why nonces must never repeat.
	block := must(aes.NewCipher(newKey()))
	gcm := must(cipher.NewGCM(block))
	fixedNonce := make([]byte, gcm.NonceSize())
	p1, p2 := []byte("transfer 100 to acct 1111"), []byte("transfer 900 to acct 6666")
	c1 := gcm.Seal(nil, fixedNonce, p1, nil)
	c2 := gcm.Seal(nil, fixedNonce, p2, nil)
	recovered := make([]byte, len(p1))
	for i := range recovered { // an observer who knows p1 learns p2
		recovered[i] = c1[i] ^ c2[i] ^ p1[i]
	}
	fmt.Printf("nonce reuse recovers: %s\n", recovered)
}

package main

import (
	"bytes"
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"

	"golang.org/x/crypto/argon2"
	"golang.org/x/crypto/bcrypt"
)

type Params struct {
	Memory  uint32 // KiB
	Time    uint32 // passes
	Threads uint8
}

// Demo-sized costs so the example runs in milliseconds. Production
// values are in the next section.
var (
	oldPolicy = Params{Memory: 4 * 1024, Time: 1, Threads: 1}
	policy    = Params{Memory: 8 * 1024, Time: 2, Threads: 1}
)

var b64 = base64.RawStdEncoding

func hash(password string, p Params) string {
	salt := make([]byte, 16)
	rand.Read(salt)
	key := argon2.IDKey([]byte(password), salt, p.Time, p.Memory, p.Threads, 32)
	return fmt.Sprintf("$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s",
		argon2.Version, p.Memory, p.Time, p.Threads, b64.EncodeToString(salt), b64.EncodeToString(key))
}

var errMalformed = errors.New("malformed password hash")

func parse(encoded string) (p Params, salt, key []byte, err error) {
	parts := strings.Split(encoded, "$")
	if len(parts) != 6 || parts[1] != "argon2id" || parts[2] != fmt.Sprintf("v=%d", argon2.Version) {
		return p, nil, nil, errMalformed
	}
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &p.Memory, &p.Time, &p.Threads); err != nil {
		return p, nil, nil, errMalformed
	}
	// A stored row is input too: refuse costs that would exhaust the server.
	if p.Memory < 1024 || p.Memory > 256*1024 || p.Time < 1 || p.Time > 10 || p.Threads < 1 {
		return p, nil, nil, errMalformed
	}
	if salt, err = b64.DecodeString(parts[4]); err != nil || len(salt) < 16 {
		return p, nil, nil, errMalformed
	}
	if key, err = b64.DecodeString(parts[5]); err != nil || len(key) != 32 {
		return p, nil, nil, errMalformed
	}
	return p, salt, key, nil
}

// verify reports whether password matches, and whether the stored hash
// should be replaced because the policy has moved on.
func verify(password, encoded string) (ok, rehash bool, err error) {
	p, salt, want, err := parse(encoded)
	if err != nil {
		return false, false, err
	}
	got := argon2.IDKey([]byte(password), salt, p.Time, p.Memory, p.Threads, uint32(len(want)))
	ok = subtle.ConstantTimeCompare(got, want) == 1
	return ok, ok && p != policy, nil
}

var errInvalidLogin = errors.New("invalid email or password")

func login(users map[string]string, email, password string) error {
	stored, found := users[email]
	if !found {
		hash(password, policy) // spend the same work for unknown accounts
		return errInvalidLogin
	}
	ok, rehash, err := verify(password, stored)
	if err != nil || !ok {
		return errInvalidLogin // same message for every failure reason
	}
	if rehash {
		users[email] = hash(password, policy) // the only moment the plaintext is available
	}
	return nil
}

// params returns the "$argon2id$v=19$m=...,t=...,p=..." part; salt and key stay private.
func params(encoded string) string { return strings.Join(strings.Split(encoded, "$")[:4], "$") }

func main() {
	users := map[string]string{"member@example.com": hash("correct horse battery", oldPolicy)}
	fmt.Println("stored:", params(users["member@example.com"]))

	fmt.Println("unknown email:", login(users, "unknown@example.com", "guess"))
	fmt.Println("wrong password:", login(users, "member@example.com", "guess"))
	fmt.Println("correct password:", login(users, "member@example.com", "correct horse battery"))
	fmt.Println("rehashed to:", params(users["member@example.com"]))
	_, rehash, _ := verify("correct horse battery", users["member@example.com"])
	fmt.Println("needs rehash now:", rehash)
	_, _, err := verify("x", "$argon2id$v=19$m=4194304,t=1,p=1$c2FsdHNhbHRzYWx0c2FsdA$AAAA") // 4 GiB
	fmt.Println("hostile parameters:", err)

	long := bytes.Repeat([]byte("a"), 72)
	h, err := bcrypt.GenerateFromPassword(long, bcrypt.MinCost) // MinCost only for the demo
	if err != nil {
		panic(err)
	}
	fmt.Println("bcrypt ignores byte 73+:", bcrypt.CompareHashAndPassword(h, append(long, "anything"...)) == nil)
	_, err = bcrypt.GenerateFromPassword(append(long, 'a'), bcrypt.MinCost)
	fmt.Println("bcrypt 73-byte input:", err)
}

// 8 slots x 19 MiB caps hashing memory near 152 MiB, whatever the traffic.
var hashSlots = make(chan struct{}, 8)

func verifyBounded(ctx context.Context, password, encoded string) (ok, rehash bool, err error) {
	select {
	case hashSlots <- struct{}{}:
		defer func() { <-hashSlots }()
	case <-ctx.Done():
		return false, false, ctx.Err() // the handler answers 503, not 500
	}
	return verify(password, encoded)
}

package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"
	"time"
)

var (
	errInvalid = errors.New("invalid token")
	errExpired = errors.New("token expired")
	errRevoked = errors.New("token revoked")
	errReuse   = errors.New("refresh token reused: family revoked")
)

type record struct {
	userID  string
	family  string // all tokens descended from one login
	expires time.Time
	used    bool
}

// Store keeps only SHA-256 digests. A leaked table cannot be replayed,
// and lookups never compare the secret itself.
type Store struct {
	byHash  map[[32]byte]*record
	revoked map[string]bool // revoked families
	now     func() time.Time
}

const prefix = "gfr_" // a recognizable prefix helps secret scanners

func (s *Store) issue(userID, family string, ttl time.Duration) string {
	raw := make([]byte, 32)
	rand.Read(raw)
	token := prefix + base64.RawURLEncoding.EncodeToString(raw)
	s.byHash[sha256.Sum256([]byte(token))] = &record{userID, family, s.now().Add(ttl), false}
	return token
}

func (s *Store) lookup(token string) (*record, error) {
	if !strings.HasPrefix(token, prefix) || len(token) != len(prefix)+43 {
		return nil, errInvalid
	}
	r, ok := s.byHash[sha256.Sum256([]byte(token))]
	switch {
	case !ok:
		return nil, errInvalid
	case s.revoked[r.family]:
		return nil, errRevoked
	case !s.now().Before(r.expires):
		return nil, errExpired
	}
	return r, nil
}

// Rotate exchanges a refresh token for a new one. Presenting an already
// used token means two parties hold it, so the whole family is revoked.
func (s *Store) Rotate(token string) (string, error) {
	r, err := s.lookup(token)
	if err != nil {
		return "", err
	}
	if r.used {
		s.revoked[r.family] = true
		return "", errReuse
	}
	r.used = true
	return s.issue(r.userID, r.family, 30*24*time.Hour), nil
}

func main() {
	now := time.Date(2026, 11, 18, 9, 0, 0, 0, time.UTC)
	s := &Store{byHash: map[[32]byte]*record{}, revoked: map[string]bool{}, now: func() time.Time { return now }}

	t1 := s.issue("user-42", "login-1", 30*24*time.Hour)
	fmt.Println("token length:", len(t1), "stored digest bytes:", len(sha256.Sum256([]byte(t1))))
	r, err := s.lookup(t1)
	fmt.Println("lookup:", r.userID, err)
	altered := []byte(t1)
	altered[10] ^= 0x01 // change one character
	_, err = s.lookup(string(altered))
	fmt.Println("altered:", err)

	t2, err := s.Rotate(t1)
	fmt.Println("rotated:", t2 != t1, err)
	_, err = s.Rotate(t1) // an attacker replays the stolen original
	fmt.Println("replay old:", err)
	_, err = s.Rotate(t2) // the legitimate client is logged out too
	fmt.Println("use new:", err)

	t3 := s.issue("user-7", "login-2", time.Hour)
	now = now.Add(61 * time.Minute)
	_, err = s.lookup(t3)
	fmt.Println("after 61 minutes:", err)
}

package main

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"slices"
	"strings"
	"time"
)

var b64 = base64.RawURLEncoding.Strict()

type header struct {
	Alg string `json:"alg"`
	Typ string `json:"typ"`
	Kid string `json:"kid"`
}

type Claims struct {
	Iss string   `json:"iss"`
	Sub string   `json:"sub"`
	Aud audience `json:"aud"`
	Exp *int64   `json:"exp"`
	Nbf *int64   `json:"nbf"`
}

// audience accepts the two RFC 7519 shapes: "a" or ["a", "b"].
type audience []string

func (a *audience) UnmarshalJSON(b []byte) error {
	var one string
	if json.Unmarshal(b, &one) == nil {
		*a = audience{one}
		return nil
	}
	return json.Unmarshal(b, (*[]string)(a))
}

// Verifier accepts exactly one algorithm, issuer and audience.
type Verifier struct {
	Keys     map[string][]byte // kid -> HMAC key
	Issuer   string
	Audience string
	Leeway   time.Duration
	Now      func() time.Time
}

func base64URLOnly(s string) bool {
	for _, c := range s {
		if !('a' <= c && c <= 'z' || 'A' <= c && c <= 'Z' || '0' <= c && c <= '9' || c == '-' || c == '_') {
			return false
		}
	}
	return s != ""
}

func (v *Verifier) Verify(token string) (*Claims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 || !base64URLOnly(parts[0]) || !base64URLOnly(parts[1]) {
		return nil, errors.New("malformed token")
	}
	var h header
	if err := decodeStrict(parts[0], &h); err != nil {
		return nil, errors.New("malformed header")
	}
	if h.Alg != "HS256" { // pinned by configuration, never chosen by the token
		return nil, fmt.Errorf("unsupported alg %q", h.Alg)
	}
	if h.Typ != "at+jwt" {
		return nil, fmt.Errorf("unexpected typ %q", h.Typ)
	}
	key, ok := v.Keys[h.Kid]
	if !ok {
		return nil, errors.New("unknown key ID")
	}
	sig, err := b64.DecodeString(parts[2])
	if !base64URLOnly(parts[2]) || err != nil || !hmac.Equal(sig, mac(key, parts[0]+"."+parts[1])) {
		return nil, errors.New("invalid signature")
	}
	// Only bytes that passed the signature check are parsed as claims.
	var c Claims
	payload, err := b64.DecodeString(parts[1])
	if err != nil || json.Unmarshal(payload, &c) != nil {
		return nil, errors.New("malformed claims")
	}
	now := v.Now()
	switch {
	case c.Exp == nil:
		return nil, errors.New("missing exp")
	case !now.Before(time.Unix(*c.Exp, 0).Add(v.Leeway)):
		return nil, errors.New("token expired")
	case c.Nbf != nil && now.Add(v.Leeway).Before(time.Unix(*c.Nbf, 0)):
		return nil, errors.New("token not valid yet")
	case c.Iss != v.Issuer:
		return nil, errors.New("wrong issuer")
	case !slices.Contains(c.Aud, v.Audience):
		return nil, errors.New("wrong audience")
	}
	return &c, nil
}

// decodeStrict rejects header fields this verifier does not understand,
// such as "crit", "jku" or "jwk".
func decodeStrict(part string, v any) error {
	raw, err := b64.DecodeString(part)
	if err != nil {
		return err
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	return dec.Decode(v)
}

func mac(key []byte, signingInput string) []byte {
	m := hmac.New(sha256.New, key)
	m.Write([]byte(signingInput))
	return m.Sum(nil)
}

// sign builds test tokens, including deliberately hostile ones.
func sign(key []byte, h, claims string) string {
	in := b64.EncodeToString([]byte(h)) + "." + b64.EncodeToString([]byte(claims))
	return in + "." + b64.EncodeToString(mac(key, in))
}

func main() {
	key := []byte("test-only-key-32-bytes-long-0001") // test key, never a real secret
	now := time.Date(2026, 11, 18, 12, 0, 0, 0, time.UTC)
	v := &Verifier{Keys: map[string][]byte{"k1": key}, Issuer: "https://auth.example", Audience: "orders-api",
		Leeway: 30 * time.Second, Now: func() time.Time { return now }}

	hdr := `{"alg":"HS256","typ":"at+jwt","kid":"k1"}`
	claims := func(aud string, exp, nbf int64) string {
		return fmt.Sprintf(`{"iss":"https://auth.example","sub":"user-42","aud":%s,"exp":%d,"nbf":%d}`, aud, exp, nbf)
	}
	t := now.Unix()
	good := sign(key, hdr, claims(`["orders-api","billing-api"]`, t+300, t-60))
	parts := strings.Split(good, ".")
	forgedPayload := b64.EncodeToString([]byte(claims(`"orders-api"`, t+86400, t-60)))

	cases := []struct{ name, token string }{
		{"valid", good},
		{"alg none", b64.EncodeToString([]byte(`{"alg":"none","typ":"at+jwt","kid":"k1"}`)) + "." + parts[1] + "."},
		{"alg switch", sign(key, `{"alg":"HS512","typ":"at+jwt","kid":"k1"}`, claims(`"orders-api"`, t+300, t-60))},
		{"jku header", sign(key, `{"alg":"HS256","typ":"at+jwt","kid":"k1","jku":"https://evil.example/k"}`, claims(`"orders-api"`, t+300, t-60))},
		{"unknown kid", sign(key, `{"alg":"HS256","typ":"at+jwt","kid":"k9"}`, claims(`"orders-api"`, t+300, t-60))},
		{"edited payload", parts[0] + "." + forgedPayload + "." + parts[2]},
		{"expired", sign(key, hdr, claims(`"orders-api"`, t-31, t-600))},
		{"not yet valid", sign(key, hdr, claims(`"orders-api"`, t+600, t+120))},
		{"other audience", sign(key, hdr, claims(`"billing-api"`, t+300, t-60))},
		{"missing exp", sign(key, hdr, `{"iss":"https://auth.example","sub":"user-42","aud":"orders-api"}`)},
	}
	for _, c := range cases {
		got, err := v.Verify(c.token)
		if err != nil {
			fmt.Printf("%-15s rejected: %v\n", c.name, err)
			continue
		}
		fmt.Printf("%-15s accepted: sub=%s aud=%v\n", c.name, got.Sub, got.Aud)
	}
}

package main

import (
	"bytes"
	"compress/gzip"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
)

const (
	maxFields   = 8
	maxValueLen = 256
)

var errMalformed = errors.New("malformed record")

type Field struct {
	Tag   byte
	Value []byte
}

// Parse decodes: count(1) then per field tag(1) || uvarint(len) || value.
// Every length is checked before it is used, and only canonical
// encodings are accepted, so Encode(Parse(b)) == b whenever Parse succeeds.
func Parse(b []byte) ([]Field, error) {
	if len(b) == 0 || b[0] > maxFields {
		return nil, fmt.Errorf("%w: field count", errMalformed)
	}
	count, b := int(b[0]), b[1:]
	fields := make([]Field, 0, count)
	for range count {
		if len(b) == 0 {
			return nil, fmt.Errorf("%w: truncated tag", errMalformed)
		}
		tag := b[0]
		n, k := binary.Uvarint(b[1:])
		switch {
		case k <= 0:
			return nil, fmt.Errorf("%w: bad length", errMalformed)
		case k != len(binary.AppendUvarint(nil, n)):
			return nil, fmt.Errorf("%w: non-minimal length", errMalformed)
		case n > maxValueLen:
			return nil, fmt.Errorf("%w: value too long", errMalformed)
		case uint64(len(b)-1-k) < n:
			return nil, fmt.Errorf("%w: truncated value", errMalformed)
		}
		b = b[1+k:]
		fields = append(fields, Field{tag, bytes.Clone(b[:n])})
		b = b[n:]
	}
	if len(b) != 0 {
		return nil, fmt.Errorf("%w: trailing bytes", errMalformed)
	}
	return fields, nil
}

func Encode(fields []Field) []byte {
	out := []byte{byte(len(fields))}
	for _, f := range fields {
		out = append(out, f.Tag)
		out = binary.AppendUvarint(out, uint64(len(f.Value)))
		out = append(out, f.Value...)
	}
	return out
}

// naiveParse trusts the declared length, the bug fuzzing finds first.
func naiveParse(b []byte) (value []byte, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic: %v", r)
		}
	}()
	n, k := binary.Uvarint(b[2:])
	return b[2+k : 2+k+int(n)], nil
}

// readAtMost refuses to inflate more than limit bytes.
func readAtMost(r io.Reader, limit int64) ([]byte, error) {
	data, err := io.ReadAll(io.LimitReader(r, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > limit {
		return nil, fmt.Errorf("decompressed body exceeds %d bytes", limit)
	}
	return data, nil
}

func main() {
	seeds := [][]byte{
		{2, 'n', 3, 'a', 'd', 'a', 'r', 1, 'x'},
		{1, 'n', 5, 'a', 'd'},
		{1, 'n', 0x80, 0x00},
		{1, 'n', 0xff, 0xff, 0xff, 0xff, 0x0f},
		{1, 'n', 1, 'a', 'z'},
		{9},
	}
	for i, s := range seeds {
		fields, err := Parse(s)
		if err != nil {
			fmt.Printf("seed %d: %v\n", i, err)
			continue
		}
		fmt.Printf("seed %d: %d fields, round trip %t\n", i, len(fields), bytes.Equal(Encode(fields), s))
	}
	_, err := naiveParse(seeds[1])
	fmt.Println("naive parser:", err)

	var bomb bytes.Buffer
	zw := gzip.NewWriter(&bomb)
	zw.Write(make([]byte, 16<<20)) // 16 MiB of zeros
	zw.Close()
	fmt.Println("compressed under 64 KiB:", bomb.Len() < 64<<10)
	zr, err := gzip.NewReader(&bomb)
	if err != nil {
		panic(err)
	}
	_, err = readAtMost(zr, 1<<20)
	fmt.Println("inflate with 1 MiB limit:", err)
}

package record

import (
	"bytes"
	"testing"
)

func FuzzParse(f *testing.F) {
	f.Add([]byte{2, 'n', 3, 'a', 'd', 'a', 'r', 1, 'x'}) // valid
	f.Add([]byte{1, 'n', 0x80, 0x00})                    // non-minimal length
	f.Add([]byte{1, 'n', 5, 'a', 'd'})                   // truncated value
	f.Add([]byte{})
	f.Fuzz(func(t *testing.T, data []byte) {
		fields, err := Parse(data) // invariant 1: never panics
		if err != nil {
			return
		}
		total := 0
		for _, fl := range fields {
			total += len(fl.Value)
		}
		// invariant 2: bounded output, never larger than the input
		if len(fields) > maxFields || total > len(data) {
			t.Fatalf("%d fields, %d value bytes from %d input bytes", len(fields), total, len(data))
		}
		// invariant 3: canonical round trip
		if enc := Encode(fields); !bytes.Equal(enc, data) {
			t.Fatalf("round trip changed %x into %x", data, enc)
		}
	})
}

package main

import (
	"fmt"
	"runtime"
	"runtime/debug"
)

// candidate is what debug/buildinfo.ReadFile returns for a release binary;
// `go version -m ./orders` prints the same record as text.
var candidate = &debug.BuildInfo{
	Path: "example.com/orders/cmd/orders",
	Main: debug.Module{Path: "example.com/orders", Version: "v1.8.0+dirty"},
	Deps: []*debug.Module{
		{Path: "example.com/auth", Version: "v0.3.1",
			Replace: &debug.Module{Path: "../auth", Version: "(devel)"}},
		{Path: "golang.org/x/crypto", Version: "v0.57.0", Sum: "h1:3ZVCjf8Ggz7zneR/EHRVx68Ctf+2pmIMP2UFhh9cC6M="},
		{Path: "golang.org/x/sys", Version: "v0.48.0", Sum: "h1:bbX/i/6MgT9BVLM9RT1thmxL04yeTAhbEz4SyadbXoo="},
	},
	Settings: []debug.BuildSetting{
		{Key: "-compiler", Value: "gc"},
		{Key: "-trimpath", Value: "true"},
		{Key: "CGO_ENABLED", Value: "0"},
		{Key: "GOOS", Value: "linux"},
		{Key: "vcs", Value: "git"},
		{Key: "vcs.revision", Value: "4b825dc642cb6eb9a060e54bf8d69288fbee4904"},
		{Key: "vcs.modified", Value: "true"},
	},
}

// audit applies a release policy to embedded build information.
func audit(bi *debug.BuildInfo) []string {
	settings := map[string]string{}
	for _, s := range bi.Settings {
		settings[s.Key] = s.Value
	}
	var problems []string
	if settings["-trimpath"] != "true" {
		problems = append(problems, "built without -trimpath")
	}
	if settings["vcs.revision"] == "" {
		problems = append(problems, "no VCS revision stamped")
	}
	if settings["vcs.modified"] != "false" {
		problems = append(problems, "built from a modified working tree")
	}
	for _, d := range bi.Deps { // a slice, so findings keep a stable order
		switch {
		case d.Replace != nil && d.Replace.Sum == "":
			problems = append(problems, d.Path+" replaced by local directory "+d.Replace.Path)
		case d.Replace == nil && d.Sum == "":
			problems = append(problems, d.Path+" has no checksum")
		}
	}
	return problems
}

func main() {
	fmt.Println("candidate:", candidate.Main.Path, candidate.Main.Version, "deps:", len(candidate.Deps))
	problems := audit(candidate)
	for _, p := range problems {
		fmt.Println("block:", p)
	}
	fmt.Println("release allowed:", len(problems) == 0)

	self, ok := debug.ReadBuildInfo() // the record embedded in this very program
	fmt.Println("self has build info:", ok)
	if ok {
		fmt.Println("self GoVersion == runtime.Version():", self.GoVersion == runtime.Version())
		fmt.Println("self dependency modules:", len(self.Deps))
	}
}
